// Pagefind wiring for the header search island [E0.3]. Kept in a plain .ts (not the .tsx)
// so the asset paths, option shape, and keyboard predicate are unit-testable without a DOM
// or React. Pure — no window, no side effects.

/** Generated by `pagefind --site dist` in the `build` step; served from the CDN. */
export const PAGEFIND_JS = "/pagefind/pagefind-ui.js";
export const PAGEFIND_CSS = "/pagefind/pagefind-ui.css";

export interface PagefindUIOptions {
  /** CSS selector or element PagefindUI mounts into. */
  element: string | HTMLElement;
  showSubResults?: boolean;
  showImages?: boolean;
  autofocus?: boolean;
  [key: string]: unknown;
}

/**
 * Default PagefindUI options for the header overlay, shared in spirit with the `/search`
 * page so both surfaces query the one index identically. `overrides` win over defaults.
 */
export function pagefindUIOptions(
  element: string | HTMLElement,
  overrides: Partial<PagefindUIOptions> = {},
): PagefindUIOptions {
  return {
    element,
    showSubResults: true,
    showImages: false,
    autofocus: true,
    ...overrides,
  };
}

/** True for the ⌘K / Ctrl+K keystroke that opens the overlay from anywhere. */
export function isOpenSearchShortcut(event: {
  key: string;
  metaKey?: boolean;
  ctrlKey?: boolean;
}): boolean {
  return Boolean(event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k";
}
